mi&gt;&lt;mo stretchy=&#34;false&#34;&gt;(&lt;/mo&gt;&lt;msub&gt;&lt;mi&gt;x&lt;/mi&gt;&lt;mn&gt;0&lt;/mn&gt;&lt;/msub&gt;&lt;mo stretchy=&#34;false&#34;&gt;)&lt;/mo&gt;&lt;/mrow&gt;&lt;/msub&gt;&lt;mo&gt;⋅&lt;/mo&gt;&lt;mfrac&gt;&lt;mi mathvariant=&#34;normal&#34;&gt;∂&lt;/mi&gt;&lt;mrow&gt;&lt;mi mathvariant=&#34;normal&#34;&gt;∂&lt;/mi&gt;&lt;msup&gt;&lt;mi&gt;x&lt;/mi&gt;&lt;mi&gt;j&lt;/mi&gt;&lt;/msup&gt;&lt;/mrow&gt;&lt;/mfrac&gt;&lt;/mrow&gt;&lt;/mstyle&gt;&lt;/mtd&gt;&lt;/mtr&gt;&lt;/mtable&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;\begin{aligned}
\frac{\partial}{\partial y^i} &amp;amp;= \sum_j \frac{\partial x^j}{\partial y^i}\cdot \frac{\partial}{\partial x^j}\\
&amp;amp;=\sum_j \frac{\partial x^j\circ \psi^{-1}}{\partial y^i}\Big|_{\psi(x_0)} \cdot \frac{\partial}{\partial x^j}\\
&amp;amp;=\sum_j \frac{\partial (\varphi\circ \psi^{-1})^j}{\partial y^i}\Big|_{\psi(x_0)}\cdot\frac{\partial }{\partial x^j}
\end{aligned}
